Here is the root cause:
Non-atomic read and clear of `engine->heartbeat.systole` allows a race between the heartbeat worker and `intel_engine_park_heartbeat()` to both call `i915_request_put()` on the same request, causing a refcount underflow.

Here is the patch:

 static void heartbeat(struct work_struct *wrk)
 {
 	struct i915_sched_attr attr = { .priority = I915_PRIORITY_MIN };
 	struct intel_engine_cs *engine =
 		container_of(wrk, typeof(*engine), heartbeat.work.work);
 	struct intel_context *ce = engine->kernel_context;
 	struct i915_request *rq;
 	unsigned long serial;

 	/* Just in case everything has gone horribly wrong, give it a kick */
 	intel_engine_flush_submission(engine);

-	rq = engine->heartbeat.systole;
-	if (rq && i915_request_completed(rq)) {
-		i915_request_put(rq);
-		engine->heartbeat.systole = NULL;
+	rq = xchg(&engine->heartbeat.systole, NULL);
+	if (rq) {
+		if (i915_request_completed(rq))
+			i915_request_put(rq);
+		else
+			engine->heartbeat.systole = rq;
 	}

 	if (!intel_engine_pm_get_if_awake(engine))
 		return;

 	if (intel_gt_is_wedged(engine->gt))
 		goto out;

 	if (i915_sched_engine_disabled(engine->sched_engine)) {
 		reset_engine(engine, engine->heartbeat.systole);
 		goto out;
 	}

 	if (engine->heartbeat.systole) {
 		long delay = READ_ONCE(engine->props.heartbeat_interval_ms);

 		/* Safeguard against too-fast worker invocations */
 		if (!time_after(jiffies,
 				rq->emitted_jiffies + msecs_to_jiffies(delay)))
 			goto out;

 		if (!i915_sw_fence_signaled(&rq->submit)) {
 			/*
 			 * Not yet submitted, system is stalled.
 			 *
 			 * This more often happens for ring submission,
 			 * where all contexts are funnelled into a common
 			 * ringbuffer. If one context is blocked on an
 			 * external fence, not only is it not submitted,
 			 * but all other contexts, including the kernel
 			 * context are stuck waiting for the signal.
 			 */
 		} else if (engine->sched_engine->schedule &&
 			   rq->sched.attr.priority < I915_PRIORITY_BARRIER) {
 			/*
 			 * Gradually raise the priority of the heartbeat to
 			 * give high priority work [which presumably desires
 			 * low latency and no jitter] the chance to naturally
 			 * complete before being preempted.
 			 */
 			attr.priority = I915_PRIORITY_NORMAL;
 			if (rq->sched.attr.priority >= attr.priority)
 				attr.priority = I915_PRIORITY_HEARTBEAT;
 			if (rq->sched.attr.priority >= attr.priority)
 				attr.priority = I915_PRIORITY_BARRIER;

 			local_bh_disable();
 			engine->sched_engine->schedule(rq, &attr);
 			local_bh_enable();
 		} else {
 			reset_engine(engine, rq);
 		}

 		rq->emitted_jiffies = jiffies;
 		goto out;
 	}

 	serial = READ_ONCE(engine->serial);
 	if (engine->wakeref_serial == serial)
 		goto out;

 	if (!mutex_trylock(&ce->timeline->mutex)) {
 		/* Unable to lock the kernel timeline, is the engine stuck? */
 		if (xchg(&engine->heartbeat.blocked, serial) == serial)
 			intel_gt_handle_error(engine->gt, engine->mask,
 					      I915_ERROR_CAPTURE,
 					      "no heartbeat on %s",
 					      engine->name);
 		goto out;
 	}

 	rq = heartbeat_create(ce, GFP_NOWAIT | __GFP_NOWARN);
 	if (IS_ERR(rq))
 		goto unlock;

 	heartbeat_commit(rq, &attr);

 unlock:
 	mutex_unlock(&ce->timeline->mutex);
 out:
-	if (!engine->i915->params.enable_hangcheck || !next_heartbeat(engine))
-		i915_request_put(fetch_and_zero(&engine->heartbeat.systole));
+	if (!engine->i915->params.enable_hangcheck || !next_heartbeat(engine)) {
+		rq = xchg(&engine->heartbeat.systole, NULL);
+		if (rq)
+			i915_request_put(rq);
+	}
 	intel_engine_pm_put(engine);
 }


 void intel_engine_park_heartbeat(struct intel_engine_cs *engine)
 {
-	if (cancel_delayed_work(&engine->heartbeat.work))
-		i915_request_put(fetch_and_zero(&engine->heartbeat.systole));
+	if (cancel_delayed_work(&engine->heartbeat.work)) {
+		struct i915_request *rq;
+
+		rq = xchg(&engine->heartbeat.systole, NULL);
+		if (rq)
+			i915_request_put(rq);
+	}
 }



